{
  "predictors": [
    {
      "name": "Social Media Sentiment Score",
      "construction": "Collect sentiment scores from blogs and social media platforms discussing the firm. Average these scores over the past month.",
      "rationale": "Investors' sentiment on social media may influence stock prices due to behavioral biases and information dissemination.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Diversity Index",
      "construction": "Calculate the proportion of female and minority board members relative to total board size.",
      "rationale": "Greater diversity may lead to better decision-making and risk management, potentially enhancing firm value.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Footprint Score",
      "construction": "Assess the firm’s carbon emissions relative to industry average, using publicly available sustainability reports.",
      "rationale": "Firms with lower environmental footprints may face less regulatory risk and appeal more to socially responsible investors.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Innovation Intensity",
      "construction": "Calculate the ratio of R&D expenditure to total sales, averaged over the last three years.",
      "rationale": "Firms investing more in R&D may generate future growth opportunities and competitive advantages.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Concentration Index",
      "construction": "Measure the percentage of purchases from the top three suppliers relative to total purchases.",
      "rationale": "High supplier concentration may indicate supply chain risks, affecting firm stability.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Customer Concentration Index",
      "construction": "Measure the percentage of sales to the top three customers relative to total sales.",
      "rationale": "High customer concentration may expose firms to demand shocks and negotiation power issues.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Count the number of citations received by a firm’s patents over the past five years.",
      "rationale": "Highly cited patents may indicate valuable and impactful innovation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Freight Cost Ratio",
      "construction": "Calculate the ratio of freight and transportation costs to total sales over the past year.",
      "rationale": "Lower freight costs may indicate efficient logistics and cost management.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Employee Satisfaction Score",
      "construction": "Aggregate employee satisfaction ratings from company reviews on employment websites over the past year.",
      "rationale": "Higher employee satisfaction can lead to improved productivity and retention, positively affecting performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Earnings Call Tone",
      "construction": "Analyze the sentiment of language used in quarterly earnings calls using natural language processing techniques.",
      "rationale": "The tone of earnings calls may reflect management’s confidence and future performance expectations.",
      "higher_returns_for": "positive values of the measure"
    }
  ]
}
